//! ════════════════════════════════════════════════════════════════════════════════════════════════
//! AN EMITTED CUDA PROGRAM SAYS TRUTHFULLY WHERE IT CAME FROM.
//!
//! The model generation lanes (Qwen3-30B-A3B batch-1 and batched, Qwen3.8-27B batch-1 and batched) are written by
//! hand: their kernels and launch sequences are templates driven by a model configuration, held to the model's
//! `.lg` forward by golden-token locks. Their emitted headers used to say they were "generated by the LOGOS
//! compiler from the forward authored in `.lg`", and a module doc said a lane was "lowered from the SAME
//! qwen30b.lg". Neither was so. Every whole-program emitter now takes its first line from
//! `codegen_cuda::provenance::header`, and this lock holds each lane to the line its provenance earns.
//! ════════════════════════════════════════════════════════════════════════════════════════════════

#![cfg(feature = "codegen")]

use logicaffeine_compile::codegen_cuda::provenance::{header, Provenance};
use logicaffeine_compile::codegen_cuda::qwen38::{emit_qwen38_generate, Qwen38Cfg};
use logicaffeine_compile::codegen_cuda::qwen38_batched::emit_qwen38_generate_batched;
use logicaffeine_compile::codegen_cuda::qwen_batched::emit_qwen30b_generate_batched;
use logicaffeine_compile::codegen_cuda::qwen_emit::{emit_qwen30b_generate, Qwen30bCfg};
use logicaffeine_compile::compile::compile_to_cuda_forward;

fn first_line(program: &str) -> String {
    format!("{}\n", program.lines().next().unwrap_or(""))
}

#[test]
fn the_compiled_forward_says_it_was_compiled() {
    let src = "## Main\n\
        Let A be a 2 by 2 tensor of Real.\n\
        Set item 1 of A to 1.0.\nSet item 4 of A to 2.0.\n\
        Let B be a 2 by 2 tensor of Real.\n\
        Set item 2 of B to 3.0.\nSet item 3 of B to 4.0.\n\
        Let C be A matmul B.\nShow item 1 of C.\n";
    let cu = compile_to_cuda_forward(src).unwrap_or_else(|e| panic!("must lower: {e}"));
    assert_eq!(first_line(&cu), header(Provenance::Compiled));
}

#[test]
fn every_hand_written_lane_says_it_is_hand_written() {
    let (q30, q38) = (Qwen30bCfg::real(), Qwen38Cfg::real());
    let lanes = [
        (
            emit_qwen30b_generate(&q30, "/weights", &[785], 4, false, true),
            Provenance::HandWritten {
                model: "Qwen3-30B-A3B",
                lane: "generation",
            },
        ),
        (
            emit_qwen30b_generate_batched(&q30, "/weights", &[785], 4, 2),
            Provenance::HandWritten {
                model: "Qwen3-30B-A3B",
                lane: "batched decode",
            },
        ),
        (
            emit_qwen38_generate(&q38, "/weights", &[760], 4, true, 3),
            Provenance::HandWritten {
                model: "Qwen3.8-27B",
                lane: "generation",
            },
        ),
        (
            emit_qwen38_generate_batched(&q38, "/weights", &[760], 4, 2, false),
            Provenance::HandWritten {
                model: "Qwen3.8-27B",
                lane: "batched decode",
            },
        ),
    ];
    let compiled = header(Provenance::Compiled);
    for (program, provenance) in lanes {
        assert_eq!(
            first_line(&program),
            header(provenance),
            "a hand-written lane's first line names it as hand-written"
        );
        assert!(
            !program.contains(compiled.trim_end()),
            "a hand-written lane never carries the compiled header ({provenance:?})"
        );
    }
}

/// The claim cannot come back by another route: no emitter source says a lane is compiled from a `.lg` it never
/// reads. The phrases are the ones the lanes used to carry.
#[test]
fn no_emitter_source_claims_a_compilation_it_does_not_do() {
    const CLAIMS: &[&str] = &[
        "generated by the LOGOS compiler from",
        "lowered from the SAME",
        "per-token math = the LOGOS forward",
    ];
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../logicaffeine_compile/src/codegen_cuda");
    let mut scanned = 0usize;
    for entry in std::fs::read_dir(&dir).unwrap_or_else(|e| panic!("{}: {e}", dir.display())) {
        let path = entry.unwrap().path();
        if path.extension().is_some_and(|x| x == "rs") {
            let text = std::fs::read_to_string(&path).unwrap();
            for claim in CLAIMS {
                assert!(
                    !text.contains(claim),
                    "{} claims `{claim}` — a lane that does not read the `.lg` says it is hand-written (provenance::header)",
                    path.display()
                );
            }
            scanned += 1;
        }
    }
    assert!(
        scanned >= 10,
        "the scan must cover the emitters, it read {scanned} files"
    );
}
